target-a-runtime" maxlength="120"></label><label>Source citation<select id="signature-target-a-source"></select></label></div><div class="target-token-row"><strong>Target token B</strong><label>Token ID<input id="signature-target-b-id" maxlength="64"></label><label>Player label<input id="signature-target-b-label" maxlength="120"></label><label>Exact Runtime target<input id="signature-target-b-runtime" maxlength="120"></label><label>Source citation<select id="signature-target-b-source"></select></label></div></div><button id="promote-signature-hunt" class="gold">Promote current route</button></section>
