function selectedPaletteAbstraction(guild){let raw=$('#instantiate-abstraction').value,at=raw.lastIndexOf('@');if(at<1)return null;let id=raw.slice(0,at),revision=Number(raw.slice(at+1));return(guild.abstractions||[]).find(x=>x.abstraction_id===id&&x.revision===revision)||null}
