function renderPalette(guild){let palette=guild.palette||[],byKey=new Map((guild.abstractions||[]).map(x=>[`${x.abstraction_id}@${x.revision}`,x]));$('#guild-palette').innerHTML=palette.length?palette.map(item=>{let abstraction=byKey.get(`${item.abstraction_id}@${item.revision}`);return`<article class="guild-ledger-card"><header><strong>${esc(abstraction?.title||item.abstraction_id)}</strong><span>r${item.revision}</span></header><p>${esc(abstraction?.explanation||'Published Guild abstraction')}</p><code>content ${esc(item.content_hash)}</code><code>source ${esc(abstraction?.source_snapshot_hash||'absent')}</code><code>invariant ${esc(abstraction?.invariant_hash||'absent')}</code></article>`}).join(''):'<div class="empty">The steward has not published an abstraction.</div>';let select=$('#instantiate-abstraction'),prior=select.value;select.innerHTML=palette.map(x=>`<option value="${esc(x.abstraction_id)}@${x.revision}">${esc(byKey.get(`${x.abstraction_id}@${x.revision}`)?.title||x.abstraction_id)} · r${x.revision}</option>`).join('');if([...select.options].some(x=>x.value===prior))select.value=prior;if(!$('#instantiate-creator').value)$('#instantiate-creator').value=guildSteward(guild);renderInstantiationTargets();$('#instantiate-signature-hunt').disabled=!palette.length}
function renderCampaignQuestlines(){let guild=selectedGuildId?guildDocs[selectedGuildId]:null,campaign=guildCampaigns(guild).find(x=>x.campaign_id===$('#campaign-placement-campaign').value),prior=$('#campaign-placement-questline').value;$('#campaign-placement-questline').innerHTML=(campaign?.questlines||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('');if((campaign?.questlines||[]).some(x=>x.id===prior))$('#campaign-placement-questline').value=prior;$('#campaign-placement-questline').disabled=$('#campaign-placement-kind').value!=='questline'}
function renderCampaigns(guild){let campaigns=guildCampaigns(guild),byProject=Object.fromEntries(projects.map(x=>[x.project_id,x]));$('#guild-campaigns').innerHTML=campaigns.length?campaigns.map(campaign=>{let artifacts=campaignArtifacts(campaign),names=artifacts.map(x=>byProject[x.project_id]?.title||x.project_id),progression=artifacts.length<2?'':`<details class="guild-compatibility"><summary>Connect campaign progression</summary><div class="guild-prerequisites">${artifacts.map(artifact=>{let chosen=new Set(artifact.prerequisite_project_ids||[]),available=artifacts.filter(x=>x.project_id!==artifact.project_id);return`<label class="guild-prerequisite-row"><strong>${esc(byProject[artifact.project_id]?.title||artifact.project_id)}</strong><small>Unlock after every selected artifact completes in the exact campaign scope.</small><select multiple data-campaign-prerequisite data-campaign-id="${esc(campaign.campaign_id)}" data-project-id="${esc(artifact.project_id)}">${available.map(x=>`<option value="${esc(x.project_id)}"${chosen.has(x.project_id)?' selected':''}>${esc(byProject[x.project_id]?.title||x.project_id)}</option>`).join('')}</select></label>`}).join('')}</div></details>`;return`<article class="guild-ledger-card"><header><strong>${esc(campaign.title)}</strong><span>r${campaign.revision}</span></header><p>${esc(campaign.creator)} · ${artifacts.length} artifact${artifacts.length===1?'':'s'}${names.length?' · '+esc(names.join(' → ')):''}</p><code>${esc(campaign.campaign_id)} · ${esc(campaign.pack_id)}@${esc(campaign.version)}</code>${progression}<div class="campaign-actions"><button class="quiet" data-campaign-action="certify" data-campaign-id="${esc(campaign.campaign_id)}">Certify</button><button class="gold" data-campaign-action="play" data-campaign-id="${esc(campaign.campaign_id)}">Play</button><button class="quiet" data-campaign-action="evidence" data-campaign-id="${esc(campaign.campaign_id)}">Evidence</button></div></article>`}).join(''):'<div class="empty">N