function renderGuildEditor(){let editor=$('#guild-editor'),guild=selectedGuildId?guildDocs[selectedGuildId]:null;editor.hidden=!guild;if(!guild)return;$('#selected-guild-name').textContent=guild.title+' creative system';$('#guild-title').value=guild.title||'';$('#guild-version').value=guild.version||'0.1.0';$('#guild-steward').value=guildSteward(guild);$('#guild-description').value=guild.description||'';$('#guild-progression').value=guild.progression_scope||'';$('#guild-compatibility').value=(guild.compatibility||[]).join(', ');$('#guild-release').value=guild.release_state||'draft';$('#archive-guild').textContent=guild.archived?'Restore guild':'Archive guild';if(!$('#new-campaign-creator').value)$('#new-campaign-creator').value=guildSteward(guild);let artifacts=guildArtifacts(guild),byId=Object.fromEntries(projects.map(x=>[x.project_id,x]));$('#guild-prerequisites').innerHTML=artifacts.length<2?'<div class="empty">Add at least two default-campaign quests to author progression.</div>':artifacts.map(a=>{let chosen=new Set(a.prerequisite_project_ids||[]),available=artifacts.filter(x=>x.project_id!==a.project_id);return`<label class="guild-prerequisite-row"><strong>${esc(byId[a.project_id]?.title||a.project_id)}</strong><small>Default-campaign alias: unlock after every selected artifact completes in this exact world, content revision, and Charm binding.</small><select multiple data-guild-prerequisite="${esc(a.project_id)}">${available.map(x=>`<option value="${esc(x.project_id)}"${chosen.has(x.project_id)?' selected':''}>${esc(byId[x.project_id]?.title||x.project_id)}</option>`).join('')}</select></label>`}).join('');renderSourceSnapshots(guild);renderSignaturePromotion(guild);renderPalette(guild);renderCampaigns(guild);showGuildLens(guildLens,false);if(campaignEvidence)renderCampaignEvidence(campaignEvidence)}
async function savePortfolioName(){if(!portfolio)return;let next=clone(portfolio);next.title=$('#portfolio-name').value.trim();try{let d=await api('/api/v2/quest-studio/portfolio',{method:'PUT',body:JSON.stringify({expected_revision:portfolio.revision,portfolio:next})});portfolio=d.portfolio;$('#portfolio-title').textContent=portfolio.title;$('#portfolio-name').value=portfolio.title;status('Portfolio saved',portfolio.title)}catch(e){status('Portfolio name unavailable',e.error||String(e),true)}}
async function saveGuildMutation(change,headline='Guild saved'){let guild=selectedGuildId?guildDocs[selectedGuildId]:null;if(!guild)return null;let next=clone(guild);change(next);try{let d=await api(`/api/v2/quest-studio/guilds/${encodeURIComponent(guild.guild_id)}`,{method:'PUT',body:JSON.stringify({expected_revision:guild.revision,guild:next})});guildDocs[guild.guild_id]=d.guild;campaignEvidence=null;await loadProjects(project?.project_id,true,true);status(headline,d.guild.title);return d.guild}catch(e){status('Guild change unavailable',e.error||String(e),true);return null}}
async function saveGuildDetails(){await saveGuildMutation(guild=>{guild.title=$('#guild-title').value.trim();guild.version=$('#guild-version').value.trim();guild.steward=$('#guild-steward').value.trim();guild.description=$('#guild-description').value;guild.progression_scope=$('#guild-progression').value;guild.compatibility=$('#guild-compatibility').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,64);guild.release_state=$('#guild-release').value;guild.archived=guild.release_state==='archived'},'Steward configuration saved')}
function uniqueGuildId(title,items,fallback){let base=stable(title,fallback),id=base,n=2,used=new Set(items.map(x=>x.id));while(used.has(id))id=`${base}-${n++}`;return id}
async function addQuestline(){let title=$('#new-questline-title').value.trim(),guild=selectedGuildId?guildDocs[selectedGuildId]:null;if(!title||!guild)return;let saved=await saveGuildMutation(next=>next.questlines.push({id:uniqueGuildId(title,next.questlines,'questline'),title,quests:[]}),'Questline added');if(saved)$('#new-questline-title').value=''}
