async function archiveSelectedGuild(){let guild=selectedGuildId?guildDocs[selectedGuildId]:null;if(!guild)return;try{let d=await api(`/api/v2/quest-studio/guilds/${encodeURIComponent(guild.guild_id)}/archive`,{method:'POST',body:JSON.stringify({expected_revision:guild.revision,archived:!guild.archived})});if(d.guild.archived)showArchived=true;$('#show-archived').setAttribute('aria-pressed',String(showArchived));$('#show-archived').classList.toggle('active',showArchived);await loadProjects(project?.project_id,true,true);status(d.guild.archived?'Guild archived':'Guild restored',d.guild.title)}catch(e){status('Archive unavailable',e.error||String(e),true)}}
async function duplicateSelectedGuild(){let guild=selectedGuildId?guildDocs[selectedGuildId]:null;if(!guild)return;try{let d=await api(`/api/v2/quest-studio/guilds/${encodeURIComponent(guild.guild_id)}/duplicate`,{method:'POST',body:JSON.stringify({expected_revision:guild.revision})});selectedGuildId=d.guild.guild_id;await loadProjects(d.projects?.[0]?.project_id||project?.project_id,false,true);status('Guild duplicated',`${d.guild.title} is an independent local fork.`)}catch(e){status('Duplicate unavailable',e.error||String(e),true)}}
function guildRequestContext(guild){return{project:requestContext(),guild_id:guild.guild_id,guild_revision:guild.revision}}
function isCurrentGuildContext(context){let guild=context?guildDocs[context.guild_id]:null;return!!guild&&selectedGuildId===context.guild_id&&guild.revision===context.guild_revision&&(!context.project||isCurrentContext(context.project))}
async function runGuildCertification(){let guild=selectedGuildId?guildDocs[selectedGuildId]:null,campaign=defaultCampaign(guild);if(!guild||!campaign)return;if(project&&!(await saveNow()))return;let context=guildRequestContext(guild),sequence=beginOperation('guild');try{let d=await api(`/api/v2/quest-studio/guilds/${encodeURIComponent(guild.guild_id)}/campaigns/${encodeURIComponent(campaign.campaign_id)}/certify`,{method:'POST'});if(!isLatestOperation('guild',sequence)||!isCurrentGuildContext(context))return;campaignEvidence=null;status('Default campaign certified',`${d.experience_ids.length} experiences · ${d.content_hash}`)}catch(e){if(!isLatestOperation('guild',sequence)||!isCurrentGuildContext(context))return;status('Default campaign certification failed',e.error||e.diagnostics?.[0]?.message||String(e),true)}}
async function publishSelectedGuild(){let guild=selectedGuildId?guildDocs[selectedGuildId]:null,campaign=defaultCampaign(guild);if(!guild||!campaign)return;if(project&&!(await saveNow()))return;let context=guildRequestContext(guild),sequence=beginOperation('guild');$('#publish-guild').disabled=true;try{let d=await api(`/api/v2/quest-studio/guilds/${encodeURIComponent(guild.guild_id)}/campaigns/${encodeURIComponent(campaign.campaign_id)}/publish`,{method:'POST',body:JSON.stringify({expected_revision:campaign.revision})});if(!isLatestOperation('guild',sequence)||!isCurrentGuildContext(context))return;campaignEvidence=null;status(d.receipt?.already_present?'Default campaign already published':'Default campaign published',`${d.experience_ids.length} experiences · ${d.content_hash}`);await refreshRuntime()}catch(e){if(!isLatestOperation('guild',sequence)||!isCurrentGuildContext(context))return;status('Default campaign publication failed',e.error||e.diagnostics?.[0]?.message||String(e),true)}finally{$('#publish-guild').disabled=false}}
async function playSelectedGuild(){let guild=selectedGuildId?guildDocs[selectedGuildId]:null,campaign=defaultCampaign(guild);if(!guild||!campaign)return;if(project&&!(await saveNow()))return;let context=guildRequestContext(guild),sequence=beginOperation('guild');$('#play-guild').disabled=true;try{let d=await api(`/api/v2/quest-studio/guilds/${encodeURIComponent(guild.guild_id)}/campaigns/${encodeURIComponent(campaign.campaign_id)}/play`,{method:'POST',body:JSON.stringify({expected_revision:campaign.revision})});if(!isLatestOperation('guild',sequence)||!isCurrentGuildContext(context))return;campaignEvidence=null;status('Default campaign sent to the game',`${d.experience_ids.length} experiences · ${d.content_hash}`);await refreshRuntime()}catch(e){if(!isLatestOperation('guild',sequence)||!isCurrentGuildContext(context))return;let detail=e.error==='dev_channel_disconnected'?'Enter the pinned authoring world, then try again.':e.error==='dev_channel_not_armed'?'Arm this creator session, then try again.':e.error||e.diagnostics?.[0]?.message||String(e);status('Default campaign play stopped',detail,true)}finally{$('#play-guild').disabled=false}}
async function exportSelectedGuild(){let guild=selectedGuildId?guildDocs[selectedGuildId]:null;if(!guild)return;try{let name=await downloadPost(`/api/v2/quest-studio/guilds/${encodeURIComponent(guild.guild_id)}/export`,{},`${guild.guild_id}.questguild.json`);status('Guild exported',name)}catch(e){status('Guild export unavailable',e.error||String(e),true)}}
async function importGuildJson(file){if(!file)return;try{if(file.size>1049600)throw{error:'guild_bundle_too_large'};let bundle;try{bundle=JSON.parse(await file.text())}catch{throw{error:'guild_bundle_invalid'}}let d=await api('/api/v2/quest-studio/guilds/import',{method:'POST',body:JSON.stringify({bundle})});selectedGuildId=d.guild.guild_id;await loadProjects(d.projects?.[0]?.project_id||project?.project_id,false,true);status('Guild imported',`${d.guild.title} opened as an independent local fork.`)}catch(e){status('Guild import unavailable',e.error||String(e),true)}finally{$('#import-guild-file').value=''}}
function acceptCreativeGuild(result){if(!result?.guild)return null;guildDocs[result.guild.guild_id]=result.guild;campaignEvidence=null;renderLibrary();renderGuildEditor();return result.guild}
async function readGuildSourceFile(id,maxBytes){let file=$('#'+id).files?.[0];if(!file)throw{error:id+'_required'};if(file.size>maxBytes)throw{error:id+'_too_large'};return await file.text()}
async function importGuildSources(){let guild=selectedGuildId?guildDocs[selectedGuildId]:null;if(!guild)return;let button=$('#import-guild-sources');button.disabled=true;try{let sourceSnapshotId=$('#guild-source-id').value.trim();if(!/^[A-Za-z0-9_.-]{1,64}$/.test(sourceSnapshotId))throw{error:'source_snapshot_id_invalid'};let [catalogJson,provenanceJson,anomaliesText]=await Promise.all([readGuildSourceFile('guild-source-catalog',4*1024*1024),readGuildSourceFile('guild-source-provenance',4*1024*1024),readGuildSourceFile('guild-source-anomalies',1024*1024)]),d=await api(`/api/v2/quest-studio/guilds/${encodeURIComponent(guild.guild_id)}/sources/import`,{method:'POST',body:JSON.stringify({expected_revision:guild.revision,source_snapshot_id:sourceSnapshotId,title:$('#guild-source-title').value.trim(),catalog_json:catalogJson,provenance_json:provenanceJson,anomalies_text:anomaliesText})});acceptCreativeGuild(d);for(let id of ['guild-source-catalog','guild-source-provenance','guild-source-anomalies'])$('#'+id).value='';status('Source snapshot imported',`${d.snapshot.entry_count} entries · ${d.snapshot.anomaly_count} anomalies · ${d.snapshot.snapshot_hash}`)}catch(e){status('Source import stopped',e.error||String(e),true)}finally{button.disabled=false}}
function signatureTargetChoice(suffix){return{id:$('#signature-target-'+suffix+'-id').value.trim(),label:$('#signature-target-'+suffix+'-label').value.trim(),runtime_target:$('#signature-target-'+suffix+'-runtime').value.trim(),source_quest_id:$('#signature-target-'+suffix+'-source').value}}
async function promoteSignatureHunt(){let guild=selectedGuildId?guildDocs[selectedGuildId]:null;if(!guild||!project)return;if(!(await saveNow()))return;let routes=signatureRoutes(),route=routes.find(x=>x.route.id===$('#signature-route').value)?.route,citations=[...$('#signature-source-quests').selectedOptions].map(x=>x.value),choices=[signatureTargetChoice('a'),signatureTargetChoice('b')];if(!route){status('Signature Hunt invariant missing','Open a kill route with weapon_skill=Spears and projectile=true.',true);return}if(citations.length<1||choices.some(x=>!x.id||!x.label||!x.runtime_target||!x.source_quest_id)){status('Exact citations required','Select source quests and complete both target token rows.',true);return}if(new Set(choices.map(x=>x.id)).size!==2||new Set(choices.map(x=>x.runtime_target)).size!==2){status('Two distinct target tokens required','Token IDs and exact Runtime targets must differ.',true);return}if(choices.some(x=>!citations.includes(x.source_quest_id))){status('Target citation missing','Each target token must cite one of the selected source quests.',true);return}let button=$('#promote-signature-hunt');button.disabled=true;try{let d=await api(`/api/v2/quest-studio/guilds/${encodeURIComponent(guild.guild_id)}/abstractions/promote`,{method:'POST',body:JSON.stringify({expected_revision:guild.revision,abstraction_id:$('#signature-abstraction-id').value.trim(),title:$('#signature-title').value.trim(),explanation:$('#signature-explanation').value.trim(),source_snapshot_id:$('#signature-source-snapshot').value,source_quest_ids:citations,project_id:project.project_id,route_id:route.id,completion_action_id:$('#signature-completion-action').value||null,attribution:$('#signature-attribution').value.trim(),evidence_policy:$('#signature-evidence-policy').value,evidence_explanation:$('#signature-evidence-explanation').value.trim(),target_choices:choices})});acceptCreativeGuild(d);guildLens='create';renderGuildEditor();status('Signature Hunt promoted',`${d.abstraction.abstraction_id} r${d.abstraction.revision} · ${d.abstraction.content_hash}`)}catch(e){status('Promotion stopped',e.error||String(e),true)}finally{button.disabled=false}}
function loadSelectedHunt(){const d=project?.derivation,guild=selectedGuildId?guildDocs[selectedGuildId]:null,abstraction=guild?.abstractions?.find(a=>a.abstraction_id===d?.abstraction_id&&a.revision===d?.abstraction_revision);if(!d||d.detached||d.guild_id!==guild?.guild_id||!abstraction?.target_spawn_action_id){status('Choose a hunt','Select a hunt made from the palette with an active-hunt target.',true);return}const palette=$('#instantiate-abstraction'),revision=abstraction.abstraction_id+'@'+abstraction.revision;if(![...palette.options].some(x=>x.value===revision))palette.add(new Option(abstraction.title+' - saved revision '+abstraction.revision,revision));palette.value=revision;renderInstantiationTargets();$('#instantiate-target').value=d.target_choice_id;$('#instantiate-mechanic').value=d.mechanic||'thrown_spear';$('#instantiate-title').value=project.title;$('#instantiate-instructions').value=project.nodes.find(n=>n.id===abstraction.entry_node_id)?.label||d.instructions;$('#instantiate-completion').value=project.nodes.flatMap(n=>n.routes||[]).find(r=>r.id===abstraction.route_id)?.actions?.find(a=>a.id===abstraction.completion_action_id)?.text||d.completion_message;$('#save-selected-hunt').dataset.projectId=project.project_id;$('#save-selected-hunt').disabled=false;$('#hunt-edit-context').textContent='Editing '+project.title+'. Saving keeps earlier playthroughs and applies the changes on replay.'}
