function evidenceValue(value){return value===null||value===undefined||value===''?'<span class="evidence-absent">absent</span>':esc(value)}
function evidenceGrid(rows){return`<dl class="evidence-grid">${rows.map(([label,value])=>`<dt>${esc(label)}</dt><dd>${evidenceValue(value)}</dd>`).join('')}</dl>`}
