function runtimeReceiptHtml(receipts,passes){let proof=(passes||[]).map(line=>`<div class="pass-line ${line.status==='FAIL'?'fail':''}"><strong>${esc(line.kind||'Runtime')}</strong><span class="pass-state">${esc(line.status||'')}</span><span>${esc(line.message||'')}</span></div>`).join(''),detail=(receipts||[]).slice(0,12).map(r=>{let stage=r.stage_id||'',kind=r.kind||'plumbing',mark={story:'◆',cast:'✦',warning:'▲'}[kind]||'·',count=r.required_count>1?` · ${r.current_count||0}/${r.required_count}`:'',labels=[r.route_label,r.effect_label].filter(Boolean),label=labels.join(' · ')||eventLabel(r.event_name,null),run=r.run_id?` · run ${String(r.run_id).slice(-8)}`:'';let why=r.not_taken?`instead of ${r.not_taken}`:r.unmet?`waiting on ${r.unmet}`:'';return`<div class="receipt-row kind-${esc(kind)}"${stage?` data-live-node="${esc(stage)}" tabindex="0"`:''}><span class="receipt-mark">${mark}</span><span class="receipt-time">${esc(String(r.at_utc||'').slice(11,19))}</span><span class="receipt-kind">${esc(r.operation||'receipt')}</span><span class="receipt-text">${esc(r.status)} · ${esc(stageName(stage))} · ${esc(label)}${count}${run}${why?`<span class="receipt-why">${esc(why)}</span>`:''}</span></div>`}).join('');return proof+detail||'<div class="empty">No live proof yet. Play this revision; the armed Runtime will return validation, transfer, activation, and gameplay evidence here.</div>'}
