function renderBindingControl(){let find=$('#find-bindings'),select=$('#binding-candidate'),bind=$('#bind-experience'),restore=$('#restore-binding'),summary=$('#binding-summary'),selectedBindingZdo=select.value,connected=!!project&&!!runState?.available&&!!runState?.connected,busy=!!pendingRunControl;find.disabled=!connected||busy;select.disabled=!connected||busy||!bindingCandidates.length;select.innerHTML=bindingCandidates.length?bindingCandidates.map(x=>`<option value="${esc(x.binding_zdo)}" data-target-kind="${esc(x.target_kind)}">${esc(x.label||x.target_kind)} · ${Number(x.distance_metres).toFixed(1)}m · ${esc(x.binding_zdo)}</option>`).join(''):'<option value="">No candidates loaded</option>';if(bindingCandidates.some(x=>x.binding_zdo===selectedBindingZdo))select.value=selectedBindingZdo;bind.disabled=select.disabled||!select.value;restore.disabled=!connected||busy||!bindingChanges.length;if(!project)summary.textContent='Choose a quest before selecting a Charm target.';else if(!connected)summary.textContent='Enter the pinned authoring world; Studio will enable exact binding when Runtime is fresh.';else if(bindingChanges.length){let last=bindingChanges[bindingChanges.length-1];summary.textContent=`${bindingCandidates.length} candidate${bindingCandidates.length===1?'':'s'} · last change ${String(last.change_id).slice(-12)} can be restored.`}else if(bindingCandidates.length)summary.textContent=`${bindingCandidates.length} bounded candidate${bindingCandidates.length===1?'':'s'} from world ${runState.world_uid}.`;else summary.textContent='Find nearby candidates. Runtime never guesses which world object receives the quest.'}
function renderRunControl(){renderBindingControl();let badge=$('#run-state'),summary=$('#run-summary'),row=$('#run-select-row'),select=$('#run-select'),preview=$('#reset-preview'),previewButton=$('#preview-reset'),confirm=$('#confirm-reset');preview.hidden=true;confirm.hidden=true;previewButton.disabled=true;row.hidden=true;if(!project){badge.className='readiness neutral';badge.textContent='Waiting';summary.textContent='Choose a quest to inspect its runs.';return}if(!runState){badge.className='readiness neutral';badge.textContent='Checking';summary.textContent='Studio is looking for the exact world, binding, participant, content, and run identity.';return}if(!runState.available||!runState.connected){badge.className='readiness bad';badge.textContent=runState.available?'Runtime offline':'Unavailable';summary.textContent=runState.error==='runtime_run_status_stale'?'Runtime run status is stale. Start or resume the game before changing a run.':'No fresh Runtime run status is available on this machine.';return}let runs=runState.runs||[];if(!runs.length){badge.className='readiness neutral';badge.textContent='No run';summary.textContent='Bind and play this quest once; Runtime will then expose its exact scoped run here.';return}let current=chosenRun();selectedRunId=current?.run_id||null;row.hidden=runs.length<2;select.innerHTML=runs.map(x=>`<option value="${esc(x.run_id)}">${esc(String(x.run_id).slice(-12))} · ${esc(x.stage_id||x.outcome||'ready')} · ${esc((x.participant_ids||[]).join(', '))}</option>`).join('');select.value=selectedRunId;badge.className='readiness good';badge.textContent=current.outcome||current.stage_id||'Active';summary.textContent=`${String(current.run_id).slice(-20)} · world ${runState.world_uid} · binding ${current.binding_zdo} · ${(current.participant_ids||[]).length} participant${(current.participant_ids||[]).length===1?'':'s'}`;previewButton.disabled=false;if(resetPreviewState?.run_id===current.run_id){let s=resetPreviewState.snapshot||{};preview.hi