async function refreshRunState(){let sequence=beginOperation('runs');if(!project){runState=null;resetPreviewState=null;renderRunControl();return}let context=requestContext();try{let d=await api(`/api/v2/quest-studio/projects/${context.project_id}/runs`);if(!isLatestOperation('runs',sequence)||!isCurrentContext(context))return;runState=d;if(!(d.runs||[]).some(x=>x.run_id===selectedRunId)){selectedRunId=null;resetPreviewState=null}renderRunControl();pollPendingRunControl()}catch(e){if(!isLatestOperation('runs',sequence)||!isCurrentContext(context))return;runState={available:false,connected:false,error:e.error||'runtime_run_status_unavailable',runs:[]};resetPreviewState=null;renderRunControl()}}
